def policy(obs, P):
    pos = obs[0]
    vel = obs[1]
    if pos <= P['pos_left']:
        return 1
    if pos >= P['pos_right']:
        if vel <= P['vel_right_thresh']:
            return 2
        return 1
    if vel >= P['vel_high']:
        return 1
    if vel <= P['vel_very_neg']:
        if pos <= P['pos_very_left']:
            return 2
        return 0
    if pos > P['pos_noop_low'] and pos < P['pos_noop_high'] and vel > P['vel_noop_low'] and vel < P['vel_noop_high']:
        return 1
    if vel >= P['vel_mid_high']:
        return 2
    if vel <= P['vel_neg']:
        if pos <= P['pos_mid']:
            return 0
        return 2
    return 0
